export const meta = {
  name: 'harness-distill-cleanup',
  description: 'Distill pi sessions about harness improvements into a progress summary and verify it',
  phases: [{ title: 'extract' }, { title: 'synthesize' }, { title: 'review' }]
};

const SESSIONS = '/home/alex/.pi/agent/sessions';
const REPO = '/home/alex/Projects/pi-harness-config';

const DEFINITION = `
We are distilling documentation about IMPROVEMENTS TO THE LOCAL PI HARNESS CONFIG (the operator's pi coding-agent setup).
Harness topics include: APPEND_SYSTEM.md, settings.json, models.json / model tiers / model routing, lean-ctx integration, context-mode, context pruning, cache optimization, pi extensions, skills (especially ce-lite), autoresearch experiments (prompt-quality, config-overhead), prompt-overhead benchmarks (bench/probe.sh), progressive disclosure, upstream radar, wayfinder research, workflow orchestration (pi-dynamic-workflows), AGENTS.md / rules changes.
EXCLUDE: documentation about the operator's application projects (FALA, mindscape-site, rooted-leader-site, Investment-Engine, bio-orchestrator, novel-writer, ArmchairFuturist, Dashboard_SI, SBPS, Skills/*) unless the doc is itself about a harness/config change.
`;

const EXTRACT_INSTRUCTIONS = `
${DEFINITION}

Your job: find sessions that CREATED OR REVISED documentation about harness improvements, and extract what each one did.

Method (important - these .jsonl files can be megabytes; do NOT read them fully):
1. Triage with grep (ripgrep/grep -liE) for keywords: harness, APPEND_SYSTEM, lean-ctx, autoresearch, ce-lite, context-mode, progressive-disclosure, model-tiers, cache-optim, probe.sh, upstream-radar, wayfinder, models.json.
2. For candidate files, grep for file-creation events: look for lines containing .md paths being written (tool calls writing files, e.g. '"path"' near '.md', or mentions of "wrote/created/updated <file>.md").
3. Read only the relevant segments around those hits (grep -o with context, or sed line ranges).
4. Note the session date from the filename (ISO timestamp prefix).

Return a plain-text report, one block per documented improvement:
- DATE: (from session filename)
- SESSION: (filename)
- DOC: (path of doc created/updated, if any)
- WHAT: 2-4 sentences - what harness improvement was made or decided, key numbers/decisions.
If a session discussed harness improvements but produced no doc, still list it with DOC: (none) and a 1-2 sentence WHAT.
If nothing in your assigned set qualifies, say so explicitly. Never return empty.
`;

phase('extract');
const extractors = [
  () => agent(`${EXTRACT_INSTRUCTIONS}\nAssigned set: ALL 7 session files in ${SESSIONS}/--home-alex-Projects-pi-harness-config--/`, { label: 'ext-repo-sessions', tier: 'medium' }),
  () => agent(`${EXTRACT_INSTRUCTIONS}\nAssigned set: ${SESSIONS}/--home-alex--/ (114 files, ~27 will grep-match; triage first, skip non-harness ones).`, { label: 'ext-home-sessions', tier: 'medium' }),
  () => agent(`${EXTRACT_INSTRUCTIONS}\nAssigned set: ${SESSIONS}/--home-alex-Projects--/ (151 files, ~83 grep-match; most are app-project sessions - aggressively exclude per the EXCLUDE rule; only keep sessions whose docs concern the harness itself).`, { label: 'ext-projects-sessions', tier: 'medium' }),
  () => agent(`${EXTRACT_INSTRUCTIONS}\nAssigned set: ${SESSIONS}/--home--/ (28 files, ~24 grep-match).`, { label: 'ext-roothome-sessions', tier: 'medium' }),
  () => agent(`${EXTRACT_INSTRUCTIONS}\nAssigned set: the benchmark-workspace session dirs under ${SESSIONS}/: --home-alex-pi-bench-ws--, --home-alex-pi-bench-ws-complex--, --home-alex-pi-pq-bench-bug--, --home-alex-pi-pq-bench-parse--, --home-alex-pi-pq-bench-stats--, --home-alex-pi-pq-bench-validate--, --home-alex-pi-pq-bench-cli--, --home-alex-pi-pq-bench-faster--, --home-alex-pi-pq-bench-errors--, --tmp-bench-workspace--, --tmp-pi-probe-ws--, and the six --home-alex-bench-results-work-*-- dirs. These were throwaway benchmark runs. Do NOT summarize them individually. Report ONLY: (a) any .md documentation file these sessions wrote OUTSIDE their own workspace (target path + 1-line content), and (b) a 3-sentence overall characterization of what was benchmarked and the headline results, if discernible.`, { label: 'ext-bench-sessions', tier: 'medium' }),
  () => agent(`Inventory ON-DISK documentation about pi harness improvements. ${DEFINITION}\nList and describe each of these (use ls/grep/head, do not dump full files):\n1. All files under ${REPO}/research/ (including wayfinder/ and the two autoresearch-* dirs: read findings.md + ideas.md headers), ${REPO}/docs/, and ${REPO}/README.md, ${REPO}/APPEND_SYSTEM.md, ${REPO}/WORKFLOW.md, ${REPO}/AGENTS.md, ${REPO}/bench/*.md if any.\n2. Current config state files: ${REPO}/settings.json, ${REPO}/models.json, ${REPO}/workflows/model-tiers.json, ${REPO}/rules/lean-ctx.md, ${REPO}/skills/ce-lite/SKILL.md - 1-2 lines each on what they configure.\n3. Stray home-root docs: /home/alex/pi-config-analysis.md, /home/alex/pi-configuration.md, /home/alex/wayfinder-agents-optimization.md, /home/alex/cachyos-performance-recommendations.md - for each: date (file mtime), 2-sentence summary, and whether it documents a harness improvement (yes/no).\nReturn a structured plain-text inventory: PATH | DATE | 1-2 sentence WHAT for every file.`, { label: 'ext-disk-docs', tier: 'medium' }),
];
const results = await parallel(extractors);
const labels = ['repo-sessions', 'home-sessions', 'projects-sessions', 'roothome-sessions', 'bench-sessions', 'disk-docs'];
const coverage = {};
let findings = '';
for (let i = 0; i < labels.length; i++) {
  coverage[labels[i]] = results[i] === null ? 'MISSING (agent returned null)' : 'ok';
  findings += `\n\n===== EXTRACTION: ${labels[i]} =====\n` + (results[i] === null ? '(agent failed - treat as missing coverage, note in summary)' : results[i]);
}
log('Extraction coverage: ' + JSON.stringify(coverage));

phase('synthesize');
const summary = await agent(`You are writing the authoritative progress summary for the operator's local pi harness configuration.

${DEFINITION}

Below are extraction reports from pi session transcripts and an on-disk docs inventory.

${findings}

Task: Write ${REPO}/docs/harness-progress-summary.md (create it with your file-writing tool). Structure:
1. **Current state** - one section: what the harness consists of TODAY (from the config-state files in the disk-docs inventory; also read ${REPO}/settings.json, ${REPO}/APPEND_SYSTEM.md, ${REPO}/workflows/model-tiers.json yourself to confirm).
2. **Timeline of improvements** - chronological (use the DATE fields; today is 2026-07-29). Each entry: date, what improved, why, and the source (doc path and/or session). Merge duplicate reports of the same event.
3. **Open threads** - anything the extractions flag as unfinished, ideas.md items not yet done, open issues.
4. **Evidence index** - table of the key docs (from disk inventory) with one-line significance.
Rules: every claim must trace to a source from the extractions or a file you read; mark anything uncertain with (?). Note any extraction block that reported missing coverage. Aim for a tight, skimmable document, not exhaustive prose.
Return the full markdown text you wrote (also return it here).`, { label: 'synthesize-summary', tier: 'big' });

phase('review');
const review = await agent(`Verify a deliverable against its contract.

Contract for ${REPO}/docs/harness-progress-summary.md:
1. File exists and has the 4 sections: Current state, Timeline of improvements, Open threads, Evidence index.
2. Timeline claims trace to sources (spot-check 5 claims against the extraction reports below; flag any unsupported).
3. No app-project documentation (FALA, mindscape, etc.) presented as harness work.
4. Missing extraction coverage, if any, is acknowledged in the document.
5. Current-state section matches the actual config files (read ${REPO}/settings.json and ${REPO}/workflows/model-tiers.json and compare).

Extraction reports:
${findings}

Read the summary file, check each term, and return: PASS or FAIL per term, with one line of evidence each. If a fixable failure exists (missing section, unsupported claim), fix the file yourself and report FIXED + what you changed.`, { label: 'review-summary', tier: 'medium' });

return { coverage, summaryWritten: summary !== null, review };

